 $('#saveBtn').onclick=saveGame;$('#loadBtn').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=ev=>{let f=ev.target.files[0];if(f){let r=new FileReader();r.onload=()=>loadGame(r.result);r.readAsText(f)}ev.target.value=''};$('#helpBtn').onclick=()=>$('#modal').classList.add('show');$('#closeModal').onclick=$('#modalOk').onclick=()=>$('#modal').classList.remove('show');
